  if (s < 0.9 || s > 1.0 + CLOWN_TAIL + 0.04) { return vec2f(1e9); }
  if (abs(c.v) - abs(prm.y * c.lat) - (prm.w + 0.008) * lb > dBest + 0.02 * lb) { return vec2f(1e9); }
