  let cup = 1.0 - 0.3 * clamp(abs(w) / 0.18, 0.0, 1.0);
  let flex = -prm.y * c.lat * along * along * cup + prm.w * along * sin(prm.z - 8.0 * along - 5.0 * abs(w)) * lb;
  return vec2f(koi_membrane(o, c.v - flex, mix(0.008, 0.0018, along) * lb), o);
