  let b = dot(oc, dir);
  let disc = b * b - (dot(oc, oc) - REEF_BOUND_R * REEF_BOUND_R);
  if (disc <= 0.0) { return h; }
  let sq = sqrt(disc);
  let ta = max(tMin, -b - sq);
  let tb = min(tMax, -b + sq);
  if (ta >= tb) { return h; }
