      albedo *= 0.88 + 0.24 * globes_noise3(vec3f(th * 3.0, u * 6.0, 1.7));
      trans = mix(vec3f(0.5, 0.06, 0.62), vec3f(0.95, 0.3, 1.0), smoothstep(0.45, 1.0, u));
