  // and a tight bright core that mostly shines through the glass and water.
  let g = max(dot(d, globesGlow), 0.0);
  c += vec3f(0.30, 0.36, 0.80) * (0.22 * pow(g, 10.0) + 0.55 * pow(g, 60.0) + 1.4 * pow(g, 400.0));

